// Imagenes locales Radio Intensa (ex-catbox, que falla intermitente).
window.RI_COVER="data:image/jpeg;base64,";
window.RI_LOGO="data:image/jpeg;base64,";
(function(){function fix(){var a=document.getElementById("imgMusicaCallada");if(a)a.src=window.RI_COVER;var b=document.getElementById("evMusicaCallada");if(b)b.src=window.RI_COVER;var f=document.querySelector(".amc-foot");if(f)f.src=window.RI_LOGO;}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",fix);else fix();})();
